import sys
import heapq
from collections import defaultdict

def min_day_to_start_playing(n, m, k, offers):
    # Create a dictionary to store the sale days for each type of microtransaction
    sale_days = defaultdict(list)
    for d, t in offers:
        sale_days[t].append(d)

    # Sort the sale days for each type
    for t in sale_days:
        sale_days[t].sort()

    # Priority queue to keep track of the next sale day for each type
    pq = []
    for t in range(1, n + 1):
        if sale_days[t]:
            heapq.heappush(pq, (sale_days[t][0], t))

    # Calculate the minimum day to buy all microtransactions
    day = 0
    total_needed = sum(k)
    total_bought = 0

    while total_bought < total_needed:
        day += 1

        # Check if there's a sale on the current day
        if pq and pq[0][0] == day:
            while pq and pq[0][0] == day:
                sale_day, t = heapq.heappop(pq)
                if sale_days[t]:
                    sale_days[t].pop(0)
                    if sale_days[t]:
                        heapq.heappush(pq, (sale_days[t][0], t))

        # Buy microtransactions
        for t in range(1, n + 1):
            if k[t - 1] > 0:
                if pq and pq[0][1] == t:
                    # Buy at sale price
                    total_bought += 1
                    k[t - 1] -= 1
                    if sale_days[t]:
                        sale_days[t].pop(0)
                        if sale_days[t]:
                            heapq.heappush(pq, (sale_days[t][0], t))
                elif k[t - 1] > 0:
                    # Buy at regular price
                    total_bought += 1
                    k[t - 1] -= 1

    return day

# Read input
n, m = map(int, input().split())
k = list(map(int, input().split()))
offers = [tuple(map(int, input().split())) for _ in range(m)]

# Calculate and print the result
result = min_day_to_start_playing(n, m, k, offers)
print(result)
